contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with all logic
    function run(address payable receiver, uint256 amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // preconditions for meaningful test
        require(receiver != address(0)); // we will contrast with zero address by later checks
        require(amount > 0);
        // ensure this contract has enough balance to attempt a transfer through c
        require(address(this).balance >= amount);

        // First: call sendTo with a valid non-zero receiver: must not revert on original
        c.sendTo(receiver, amount); if (__ESBMC_reverted()) return;

        // Record balance of this contract after the successful send (should have decreased by amount only if c actually sent out funds)
        uint256 balAfterValid = address(this).balance;

        // Now attempt the call that distinguishes the mutant: sending to zero address should revert in the original
        bool revertedWhenZero;
        // call low-level to detect revert without bubbling
        bool ok; c.sendTo(address(0), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
        revertedWhenZero = !ok;

        // The distinguishing rule: when a previous valid send succeeded, calling sendTo to the zero address MUST revert (so revertedWhenZero == true)
        // This holds for original P (because it requires receiver != address(0)) and fails for mutant M (which removed that require and thus the call may not revert here)
        assert(revertedWhenZero == true);
    }

    // allow this contract to receive Ether for funding the test
    receive() external payable {}
}
